import os
import shutil

def mirror(path1, path2):
    if not os.path.exists(path2):
        os.makedirs(path2)

    for root, dirs, files in os.walk(path1, topdown=False):
        for name in files:
            src = os.path.join(root, name)
            dst = os.path.join(path2, name)
            shutil.copy(src, dst)
            os.chmod(dst, 0o600)

